import{_ as a,o as r,c as o,aN as s}from"./chunks/framework.D31DlcCL.js";const e="/img/math-shape-cutting.svg",d=JSON.parse('{"title":"图形变变变：有趣的图形剪拼","description":"把一个正方形剪成两半，能拼出什么？本文带小朋友们走进图形的魔幻世界，锻炼空间想象力。","frontmatter":{"title":"图形变变变：有趣的图形剪拼","date":"2026-02-10T10:00:00.000Z","categories":["数学"],"tags":["小学数学","空间想象","图形剪拼","几何基础"],"description":"把一个正方形剪成两半，能拼出什么？本文带小朋友们走进图形的魔幻世界，锻炼空间想象力。","cover":"/img/math-shape-cutting.svg","top_img":"/img/math-shape-cutting.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-shape-transformation.md","filePath":"posts/primary-math-shape-transformation.md","lastUpdated":null}'),n={name:"posts/primary-math-shape-transformation.md"};function i(l,t,p,h,g,m){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="图形变变变-有趣的图形剪拼" tabindex="-1">图形变变变：有趣的图形剪拼 <a class="header-anchor" href="#图形变变变-有趣的图形剪拼" aria-label="Permalink to &quot;图形变变变：有趣的图形剪拼&quot;">​</a></h1><p>在数学的世界里，图形就像乐高积木一样，可以拆开，也可以组合。这种**“剪一剪、拼一拼”**的游戏，不仅好玩，还能锻炼我们的空间想象力。</p><p>今天，我们就来看看图形是如何完成“华丽变身”的。</p><hr><h2 id="一、-长方形的变身-从四边形到三角形" tabindex="-1">一、 长方形的变身：从四边形到三角形 <a class="header-anchor" href="#一、-长方形的变身-从四边形到三角形" aria-label="Permalink to &quot;一、 长方形的变身：从四边形到三角形&quot;">​</a></h2><p>如果你有一个长方形纸片，沿着对角线剪开，你会得到两个一模一样的直角三角形。</p><p><img src="'+e+'" alt="图形剪拼图解"></p><p><strong>【拼法 1：大三角形】</strong> 把这两个三角形的短边对齐拼在一起，你会发现它们变成了一个巨大的<strong>大三角形</strong>！</p><p><strong>【拼法 2：平行四边形】</strong> 如果把它们的斜边（最长的那条边）对齐并错位移动，嘿！它又变成了一个<strong>平行四边形</strong>。</p><hr><h2 id="二、-正方形的魔术-七巧板的奥秘" tabindex="-1">二、 正方形的魔术：七巧板的奥秘 <a class="header-anchor" href="#二、-正方形的魔术-七巧板的奥秘" aria-label="Permalink to &quot;二、 正方形的魔术：七巧板的奥秘&quot;">​</a></h2><p>正方形是剪拼界的“全能选手”。著名的<strong>七巧板</strong>（Tangram）就是由一个正方形剪出来的：</p><ul><li>5 个三角形</li><li>1 个正方形</li><li>1 个平行四边形</li></ul><p>用这 7 块小图形，你可以拼出成千上万种形状：奔跑的人、飞翔的鸟、静止的房子。</p><hr><h2 id="三、-剪拼的核心秘诀-面积不变" tabindex="-1">三、 剪拼的核心秘诀：面积不变 <a class="header-anchor" href="#三、-剪拼的核心秘诀-面积不变" aria-label="Permalink to &quot;三、 剪拼的核心秘诀：面积不变&quot;">​</a></h2><p>无论你怎么剪，怎么拼，图形的总大小（面积）是<strong>没有变化</strong>的。</p><ul><li><strong>剪开</strong>：是把一个大面积分成几个小面积。</li><li><strong>拼合</strong>：是把几个小面积合在一起。</li></ul><hr><h2 id="四、-经典例题-补全正方形" tabindex="-1">四、 经典例题：补全正方形 <a class="header-anchor" href="#四、-经典例题-补全正方形" aria-label="Permalink to &quot;四、 经典例题：补全正方形&quot;">​</a></h2><p><strong>题目</strong>：下图中缺了一个角，请问右边哪个小图形能把它补成一个完整的正方形？ <em>(这里通常会给出一组凹凸契合的图形)</em></p><p><strong>解析</strong>：</p><ol><li><strong>看形状</strong>：观察缺口的轮廓，是直的还是斜的。</li><li><strong>数格子</strong>：如果是在格点纸上，数一数缺口占了几个格。</li><li><strong>匹配</strong>：寻找能完美“卡”进去的那个伙伴。</li></ol><hr><h2 id="五、-练一练-动手实践" tabindex="-1">五、 练一练（动手实践） <a class="header-anchor" href="#五、-练一练-动手实践" aria-label="Permalink to &quot;五、 练一练（动手实践）&quot;">​</a></h2><ol><li><strong>动手剪一剪</strong>：拿一张长方形纸，只剪一刀，把它变成两个三角形。</li><li><strong>挑战拼一拼</strong>：用两个一模一样的等腰直角三角形，你能拼出多少种不同的图形？（提示：至少能拼出 3 种！）</li><li><strong>寻找对称</strong>：拼出的图形中，哪些是左右对称的？</li></ol><hr><p><em>总结：图形剪拼不仅是手指的运动，更是大脑的体操。多去尝试不同的拼法，你会发现几何世界的无穷乐趣！</em></p>',28)])])}const u=a(n,[["render",i]]);export{d as __pageData,u as default};
